// MOCK DATA: club ratings, fixture-list pool and prize ladders taken from the Last Man Standing prototype
// (ratings from the Playbook Football player database, ladders priced at 95% of 1/P(reach round) with best play).
// Mock only: the real backend owns this data. Kept on one long line per value to stay compact.
export type RawTeam = [code: string, name: string, ovr: number, att: number, def: number, cre: number, scorers: Array<[string, number]>];
export type ModeData = {
  /** Top prize multiplier (the 20th rung). */
  top: number;
  /** Pool of fixture lists: each is a permutation of the 20 club indexes. */
  pool: number[][];
  /** One prize ladder (20 multipliers) per fixture list in the pool. */
  ladders: number[][];
  /** Exact chance of reaching each round with best play, per fixture list. */
  best: number[][];
  /** Same chance when always backing the biggest OVR gap, per league and fixture list. */
  gap: Record<string, number[][]>;
};
export type LmsData = { leagues: Record<string, { name: string; teams: RawTeam[] }>; modes: Record<string, ModeData> };

